files.style.css:
:root { color-scheme: dark; font-family: Inter, ui-sans-serif, system-ui, sans-serif; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; background: radial-gradient(circle at 50% 20%, #27304d, #080a11 55%); color: #f4f7ff; }
.shell { width: min(760px, calc(100% - 32px)); padding: clamp(28px, 6vw, 64px); border: 1px solid rgba(255,255,255,.18); border-radius: 28px; background: rgba(9,12,22,.72); box-shadow: 0 30px 100px rgba(0,0,0,.45); backdrop-filter: blur(18px); }
.eyebrow { letter-spacing: .18em; font-size: .72rem; opacity: .65; }
h1 { margin: .35em 0; font-size: clamp(2.5rem, 8vw, 5.6rem); line-height: .92; max-width: 8ch; }
#status { max-width: 48ch; opacity: .78; }
button { margin-top: 1.25rem; padding: .9rem 1.2rem; border-radius: 999px; border: 1px solid rgba(255,255,255,.24); background: #f4f7ff; color: #0a0c14; font: inherit; font-weight: 700; cursor: pointer; }
button:active { transform: translateY(1px) scale(.99); }
.counter { margin-bottom: 0; opacity: .7; }

files.app.js:
const button = document.querySelector('#pulse');
const count = document.querySelector('#count');
const status = document.querySelector('#status');
let value = 0;
button.addEventListener('click', () => {
  value += 1;
  count.textContent = String(value);
  status.textContent = value === 1 ? 'Interaction observed in the browser.' : `Interaction observed ${value} times.`;
});
